// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(uint256(h) != 0); // any nonzero guess must be stored verbatim
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);
        (, bytes32 stored) = c.guesses(actor);
        assertTrue(stored == h);
    }
}
